from typing import List

def max_fill(grid, capacity):
    import math

    def dfs(x, y, visited, bucket):
        if x < 0 or x >= len(grid) or y < 0 or y >= len(grid[0]) or grid[x][y] <= 0 or (x, y) in visited:
            return 0

        if grid[x][y] == 0:
            return 0

        visited.add((x, y))
        bucket[0] += 1
        if x > 0 and grid[x-1][y] > 0:
            dfs(x-1, y, visited, bucket)
        if y > 0 and grid[x][y-1] > 0:
            dfs(x, y-1, visited, bucket)
        if x < len(grid) - 1 and grid[x+1][y] > 0:
            dfs(x+1, y, visited, bucket)
        if y < len(grid[0]) - 1 and grid[x][y+1] > 0:
            dfs(x, y+1, visited, bucket)

        visited.remove((x, y))
        bucket[0] -= 1
        return bucket[0]

    n, m = len(grid), len(grid[0])
    visited = set()
    bucket = [0] * n
    bucket[0] = 0

    for y in range(m):
        for x in range(n):
            if grid[x][y] > 0:
                dfs(x, y, visited, bucket)

    return sum(bucket)

