import math

def bf(planet1, planet2):
    '''
    There are eight planets in our solar system: the closerst to the Sun 
    is Mercury, the next one is Venus, then Earth, Mars, Jupiter, Saturn, 
    Uranus, Neptune.
    Write a function that takes two planet names as strings planet1 and planet2. 
    The function should return a tuple containing all planets whose orbits are 
    located between the orbit of planet1 and the orbit of planet2, sorted by 
    the proximity to the sun. 
    The function should return an empty tuple if planet1 or planet2
    are not correct planet names. 
    Examples
    bf("Jupiter", "Neptune") ==> ("Saturn", "Uranus")
    bf("Earth", "Mercury") ==> ("Venus")
    bf("Mercury", "Uranus") ==> ("Venus", "Earth", "Mars", "Jupiter", "Saturn")
    '''
    if planet1 not in ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus"]:
        return ()
    if planet2 not in ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus"]:
        return ()

    orbits = ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus"]
    planets = ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn"]
    distance = 149.6e6  # average distance of Earth from the Sun

    def is_within_orbit(position, distance):
        return abs(position - distance) < 1000

    def is_close_to_sun(position):
        return abs(position) < 20000  # 20000 meters is the distance from the center of the Sun to each planet

    closest_planets = []
    for i, planet in enumerate(planets):
        if is_close_to_sun(planet):
            for j, orbit in enumerate(orbits):
                if is_within_orbit(planet, distance):
                    if j in closest_planets:
                        if planet < closest_planets[j]:
                            closest_planets[j] = planet
                    else:
                        closest_planets.append(j)

    return tuple(closest_planets)
