def do_algebra(operator, operand):
    if len(operand) == 0:
        return None

    # Check if all elements in operand are integers
    if not all(isinstance(i, int) for i in operand):
        return None

    # Check for division by zero
    if len(operand) == 2 and operand[1] == 0:
        return None

    # Check for real division by 0
    if operand[1] == 0 and len(operand) > 2:
        return None

    # Check for negative numbers in operand
    if any(i < 0 for i in operand):
        return None

    # Check for operators in operand
    for i in range(len(operand)):
        if operand[i] in operator:
            return operand[i]

    return None
